    86	static ssize_t velawear_ble_write_threshold(struct bt_conn *conn,
    87	                                            const struct bt_gatt_attr *attr,
    88	                                            const void *buf, uint16_t len,
    89	                                            uint16_t offset, uint8_t flags)
    90	{
    91	  const uint8_t *data = (const uint8_t *)buf;
    92	  uint16_t seconds;
    93	
    94	  (void)conn;
    95	  (void)attr;
    96	  if (buf == NULL || offset != 0 || len != sizeof(uint16_t) ||
    97	      (flags & BT_GATT_WRITE_FLAG_PREPARE) != 0)
    98	    {
    99	      return -EINVAL;
   100	    }
   101	
   102	  seconds = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
   103	  if (seconds < 10 || seconds > 3600)
   104	    {
   105	      return -EINVAL;
   106	    }
   107	
   108	  pthread_mutex_lock(&g_lock);
   109	  g_config->sedentary_threshold_sec = seconds;
   110	  pthread_mutex_unlock(&g_lock);
   111	  syslog(LOG_INFO, "[BLE] Sedentary threshold updated: %u s\n",
   112	         (unsigned int)seconds);
   113	  return len;
   114	}
