   124	static ssize_t velawear_ble_status_ccc_write(
   125	    struct bt_conn *conn, const struct bt_gatt_attr *attr, uint16_t value)
   126	{
   127	  struct bt_conn *old_conn;
   128	  bool enabled = (value & BT_GATT_CCC_NOTIFY) != 0;
   129	
   130	  (void)attr;
   131	  old_conn = NULL;
   132	
   133	  pthread_mutex_lock(&g_lock);
   134	  old_conn = g_status_notify_conn;
   135	  g_status_notify_conn = enabled && conn != NULL ? bt_conn_ref(conn) : NULL;
   136	  g_status_notify_enabled = enabled;
   137	  pthread_mutex_unlock(&g_lock);
   138	
   139	  if (old_conn != NULL)
   140	    {
   141	      bt_conn_unref(old_conn);
   142	    }
   143	
   144	  if (enabled)
   145	    {
   146	      (void)k_work_submit(&g_status_notify_work);
   147	    }
   148	
   149	  return sizeof(value);
   150	}
