   219	int velawear_ble_init(velawear_config_t *config)
   220	{
   221	  int ret;
   222	
   223	  if (config == NULL)
   224	    {
   225	      return VELAWEAR_ERR_INVAL;
   226	    }
   227	
   228	  g_config = config;
   229	  ret = pthread_mutex_init(&g_lock, NULL);
   230	  if (ret != 0)
   231	    {
   232	      g_config = NULL;
   233	      return -ret;
   234	    }
   235	
   236	  g_alert_active = false;
   237	  g_status_notify_enabled = false;
   238	  g_status_notify_conn = NULL;
   239	  k_work_init(&g_status_notify_work, velawear_ble_notify_work);
   240	  g_motion_type = 0;
   241	  g_intensity_percent = 0;
   242	
   243	  ret = bt_enable(NULL);
   244	  if (ret < 0)
   245	    {
   246	      pthread_mutex_destroy(&g_lock);
   247	      g_config = NULL;
   248	      syslog(LOG_WARNING, "[BLE] Bluetooth init failed: %d\n", ret);
   249	      return ret;
   250	    }
   251	
   252	  ret = bt_le_adv_start(&g_advertising_param,
   253	                        g_advertising_data, ARRAY_SIZE(g_advertising_data),
   254	                        g_scan_response_data, ARRAY_SIZE(g_scan_response_data));
   255	  if (ret < 0)
   256	    {
   257	      pthread_mutex_destroy(&g_lock);
   258	      g_config = NULL;
   259	      syslog(LOG_WARNING, "[BLE] Advertising start failed: %d\n", ret);
   260	      return ret;
   261	    }
   262	
   263	  g_initialized = true;
   264	  syslog(LOG_INFO, "[BLE] VelaWear GATT service registered; advertising\n");
   265	  return VELAWEAR_OK;
   266	}
   267	
   268	void velawear_ble_cleanup(void)
   269	{
   270	  if (!g_initialized)
   271	    {
   272	      return;
   273	    }
   274	
   275	  struct bt_conn *conn;
   276	
   277	  g_initialized = false;
   278	  pthread_mutex_lock(&g_lock);
   279	  g_status_notify_enabled = false;
   280	  conn = g_status_notify_conn;
   281	  g_status_notify_conn = NULL;
   282	  pthread_mutex_unlock(&g_lock);
   283	
   284	  if (conn != NULL)
   285	    {
   286	      bt_conn_unref(conn);
   287	    }
   288	
   289	  pthread_mutex_destroy(&g_lock);
   290	  g_config = NULL;
   291	}
