   293	void velawear_ble_update_motion(int motion_type, float intensity)
   294	{
   295	  bool notify;
   296	  if (!g_initialized)
   297	    {
   298	      return;
   299	    }
   300	
   301	  if (intensity < 0.0f)
   302	    {
   303	      intensity = 0.0f;
   304	    }
   305	  if (intensity > 1.0f)
   306	    {
   307	      intensity = 1.0f;
   308	    }
   309	
   310	  pthread_mutex_lock(&g_lock);
   311	  g_motion_type = motion_type;
   312	  g_intensity_percent = (uint8_t)(intensity * 100.0f);
   313	  notify = g_status_notify_enabled;
   314	  pthread_mutex_unlock(&g_lock);
   315	
   316	  if (notify)
   317	    {
   318	      velawear_ble_notify_current_status();
   319	    }
   320	}
